#!/usr/bin/env node
// Adds native/ios/SonoraIntents.swift (Siri / Shortcuts actions) to the App
// target of the generated Xcode project. Safe to run more than once.
//
//   node scripts/ios-add-intents.mjs
//
// Apple only picks up App Shortcuts from the app target itself, and ios/ is
// generated by `npx cap add ios`, so the file is copied in and registered in
// project.pbxproj next to AppDelegate.swift.

import { copyFileSync, readFileSync, writeFileSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";

const root = join(dirname(fileURLToPath(import.meta.url)), "..");
const NAME = "SonoraIntents.swift";
const FILE_REF = "5A0A5A0A5A0A5A0A5A0A0002";   // fixed ids: re-running finds them
const BUILD_FILE = "5A0A5A0A5A0A5A0A5A0A0001";

copyFileSync(join(root, "native/ios", NAME), join(root, "ios/App/App", NAME));

const pbxPath = join(root, "ios/App/App.xcodeproj/project.pbxproj");
let pbx = readFileSync(pbxPath, "utf8");
if (pbx.includes(FILE_REF)) {
  console.log(`${NAME} already in the Xcode project`);
  process.exit(0);
}

// Each anchor is an AppDelegate.swift line of the Capacitor template.
const inserts = [
  [/(\t*)(\w{24}) \/\* AppDelegate\.swift in Sources \*\/ = \{isa = PBXBuildFile;[^\n]*\n/,
   (m, ind) => `${m}${ind}${BUILD_FILE} /* ${NAME} in Sources */ = {isa = PBXBuildFile; fileRef = ${FILE_REF} /* ${NAME} */; };\n`],
  [/(\t*)(\w{24}) \/\* AppDelegate\.swift \*\/ = \{isa = PBXFileReference;[^\n]*\n/,
   (m, ind) => `${m}${ind}${FILE_REF} /* ${NAME} */ = {isa = PBXFileReference; lastKnownFileType = sourcecode.swift; path = ${NAME}; sourceTree = "<group>"; };\n`],
  [/(\t*)(\w{24}) \/\* AppDelegate\.swift \*\/,\n/,
   (m, ind) => `${m}${ind}${FILE_REF} /* ${NAME} */,\n`],
  [/(\t*)(\w{24}) \/\* AppDelegate\.swift in Sources \*\/,\n/,
   (m, ind) => `${m}${ind}${BUILD_FILE} /* ${NAME} in Sources */,\n`],
];
for (const [re, fn] of inserts) {
  if (!re.test(pbx)) {
    console.error(`Couldn't find where to add ${NAME} in project.pbxproj (${re}). Is ios/ a Capacitor project?`);
    process.exit(1);
  }
  pbx = pbx.replace(re, fn);
}
writeFileSync(pbxPath, pbx);
console.log(`Added ${NAME} to the App target`);
